private fun collectBlockCalls(root: USimpleNameReferenceExpression, buildCall: UCallExpression): List<UCallExpression> {
    val block = buildCall.getParentOfType(UBlockExpression::class.java) ?: return emptyList()
    val name = root.identifier
    val result = mutableListOf<UCallExpression>()
    for (statement in block.expressions) {
        // skip statements after buildCall? We can include all before buildCall.
        if (statement === buildCall || statement === buildCall.uastParent) ... hard.
        // Just collect all calls on same variable in block.
        collectCallsInExpression(statement, name, result)
    }
    return result
}

private fun collectCallsInExpression(expr: UExpression, name: String, result: MutableList<UCallExpression>) {
    when (expr) {
        is UQualifiedReferenceExpression -> {
            val selector = expr.selector
            if (selector is UCallExpression) {
                val receiver = expr.receiver
                if (receiver is USimpleNameReferenceExpression && receiver.identifier == name) {
                    result.add(selector)
                } else if (receiver is UQualifiedReferenceExpression) {
                    // chain on variable: e.g., builder.setA().setB()
