                    while (root.receiver is UQualifiedReferenceExpression) root = root.receiver as UQualifiedReferenceExpression
                    if (root.receiver is USimpleNameReferenceExpression && (root.receiver as USimpleNameReferenceExpression).identifier == name) {
                        // add all selectors in chain
